        role: "system",\
        content: "You are a helpful assistant designed to output JSON.",\
      },\
      {\
        role: "user",\
        content:\
          "Who won the world series in 2020? Please respond in the format {winner: ...}",\
      },\
    ],
    store: true,
    response_format: { type: "json_object" },
  });

